body.zh:
type Route = { path: string };

// satisfies:检查形状,同时保留键名 home/about 的精确类型
const routes = { home: { path: "/" }, about: { path: "/about" } } satisfies Record<string, Route>;
routes.home; // OK,有自动补全

// 变量注解:拓宽为 Record,之后可以继续加键
const cache: Record<string, Route> = {};
cache.anything = { path: "/x" };

body.en:
type Route = { path: string };

// satisfies: checks the shape and keeps the exact keys home/about
const routes = { home: { path: "/" }, about: { path: "/about" } } satisfies Record<string, Route>;
routes.home; // OK, with autocomplete

// variable annotation: widens to Record, so keys can be added later
const cache: Record<string, Route> = {};
cache.anything = { path: "/x" };
